12	/// Given a path (absolute or relative) to a resource file, returns the
13	/// relative path from the bundle resources directory where that resource
14	/// should be stored.
15	pub fn resource_relpath(path: &Path) -> PathBuf {
16	  let mut dest = PathBuf::new();
17	  for component in path.components() {
18	    match component {
19	      Component::Prefix(_) => {}
20	      Component::RootDir => dest.push("_root_"),
21	      Component::CurDir => {}
22	      Component::ParentDir => dest.push("_up_"),
23	      Component::Normal(string) => dest.push(string),
24	    }
25	  }
26	  dest
27	}
