29	fn normalize(path: &Path) -> PathBuf {
30	  let mut dest = PathBuf::new();
31	  for component in path.components() {
32	    match component {
33	      Component::Prefix(_) => {}
34	      Component::RootDir => dest.push("/"),
35	      Component::CurDir => {}
36	      Component::ParentDir => dest.push(".."),
37	      Component::Normal(string) => dest.push(string),
38	    }
39	  }
40	  dest
41	}
