43	/// Parses the external binaries to bundle, adding the target triple suffix to each of them.
44	pub fn external_binaries(external_binaries: &[String], target_triple: &str) -> Vec<String> {
45	  let mut paths = Vec::new();
46	  for curr_path in external_binaries {
47	    paths.push(format!(
48	      "{}-{}{}",
49	      curr_path,
50	      target_triple,
51	      if target_triple.contains("windows") {
52	        ".exe"
53	      } else {
54	        ""
55	      }
56	    ));
57	  }
58	  paths
59	}
