+    impl<'a> Read for SlowReader<'a> {
+        fn read(&mut self, buf: &mut [u8]) -> Result<usize> {
+            if self.current_position >= self.buffer.len() {
+                return Ok(0);
+            }
+            buf[0] = self.buffer[self.current_position];
+            self.current_position += 1;
+            return Ok(1);
+        }
+    }
