+    pub fn remove_if<Q, F: FnOnce(&V) -> bool>(&self, key: &Q, condition: F) -> bool
+    where
+        Q: Equivalent<K> + Hash + ?Sized,
+    {
+        self.remove_entry(
+            key,
+            self.hash(key),
+            |v: &mut V| condition(v),
+            |r| r.is_some(),
+            &mut (),
+            &Guard::new(),
