+impl<K, V, H> Drop for Reserve<'_, K, V, H>
+where
+    K: 'static + Clone + Eq + Hash,
+    V: 'static + Clone,
+    H: BuildHasher,
+{
+    #[inline]
+    fn drop(&mut self) {
+        let result = self
+            .hashindex
+            .minimum_capacity
+            .fetch_sub(self.additional, Relaxed);
+        self.hashindex.try_resize(0, &Guard::new());
+        debug_assert!(result >= self.additional);
+    }
+}
