+    /// assert!(hashmap.insert(1, 0).is_ok());
+    /// assert_eq!(hashmap.insert(1, 1).unwrap_err(), (1, 1));
+    /// ```
+    #[inline]
+    pub fn insert(&self, key: K, val: V) -> Result<(), (K, V)> {
+        let guard = Guard::new();
+        let hash = self.hash(&key);
+        if let Ok(Some((k, v))) = self.insert_entry(key, val, hash, &mut (), &guard) {
+            Err((k, v))
