+    /// assert!(hashmap.update(&1, |_, _| true).is_none());
+    /// assert!(hashmap.insert(1, 0).is_ok());
+    /// assert_eq!(hashmap.update(&1, |_, v| { *v = 2; *v }).unwrap(), 2);
