+        U: FnOnce(&K, &mut V) -> R,
+    {
+        let guard = Guard::new();
+        let LockedEntry {
+            mut locker,
+            data_block_mut,
+            mut entry_ptr,
+            index: _,
+        } = self
+            .get_entry(key, self.hash(key), &mut (), &guard)
+            .ok()
+            .flatten()?;
+        let (k, v) = entry_ptr.get_mut(data_block_mut, &mut locker);
