+impl<K, V, H> Drop for Reserve<'_, K, V, H>
+where
+    K: Eq + Hash,
+    H: BuildHasher,
+{
+    #[inline]
+    fn drop(&mut self) {
+        let result = self
+            .hashmap
+            .minimum_capacity
+            .fetch_sub(self.additional, Relaxed);
+        self.hashmap.try_resize(0, &Guard::new());
+        debug_assert!(result >= self.additional);
+    }
+}
