+                            let guard = Guard::new();
+                            let mut range_scanner = tree_clone.range((first_key + 1).., &guard);
+                            let entry = range_scanner.next().unwrap();
+                            assert_eq!(entry, (&key_at_halfway, &key_at_halfway));
