+impl<'g, K, V, Q, R> Iterator for Range<'_, 'g, K, V, Q, R>
+where
+    K: 'static + Clone + Ord,
+    V: 'static + Clone,
+    Q: Comparable<K> + ?Sized,
+    R: RangeBounds<Q>,
+{
