+        // Starts scanning from the minimum key.
+        let mut min_scanner = self.min(guard)?;
+        min_scanner.next();
+        loop {
+            if let Some((k, _)) = min_scanner.get() {
+                if key.compare(k).is_ge() {
+                    return Some(min_scanner);
+                }
+                break;
+            }
+            min_scanner = min_scanner.jump(None, guard)?;
+        }
