+                            | InsertResult::Frozen(..) => return Ok(insert_result),
+                            InsertResult::Full(k, v) => {
+                                let split_result = self.split_node(
+                                    k,
+                                    v,
+                                    Some(child_key),
+                                    child_ptr,
+                                    child,
+                                    false,
+                                    async_wait,
+                                    guard,
+                                )?;
+                                if let InsertResult::Retry(k, v) = split_result {
+                                    key = k;
+                                    val = v;
+                                    continue;
+                                }
+                                return Ok(split_result);
+                            }
