+        }
+        assert_eq!(
+            Leaf::<usize, usize>::optimal_boundary(leaf.metadata.load(Relaxed)),
+            1
+        );
+
+        let leaf: Leaf<usize, usize> = Leaf::new();
+        for i in 0..DIMENSION.num_entries {
+            if i < DIMENSION.num_entries / 2 {
