+#![deny(missing_docs, warnings, clippy::all, clippy::pedantic)]
+#![doc = include_str!("../README.md")]
+
+mod atomic_owned;
+pub use atomic_owned::AtomicOwned;
+
+mod atomic_shared;
+pub use atomic_shared::AtomicShared;
+
+mod guard;
+pub use guard::Guard;
+
+mod epoch;
+pub use epoch::Epoch;
+
+mod owned;
